const FEATURE_VERSION='0.4.4',ASSET_BUILD='044',featureLoads=new Map();
function loadFeatureScript(name){if(featureLoads.has(name))return featureLoads.get(name);const p=new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=`/${name}.js?v=${FEATURE_VERSION}&build=${ASSET_BUILD}`;el.defer=true;el.onload=resolve;el.onerror=()=>reject(Error(`功能模块加载失败：${name}`));document.head.appendChild(el)});featureLoads.set(name,p);return p}
async function ensureFeature(kind){try{if(kind==='music')await loadFeatureScript('music-ui');else if(kind==='pages')await loadFeatureScript('app-games');else if(kind==='games'){await Promise.all([loadFeatureScript('game-dice'),loadFeatureScript('game-poker'),loadFeatureScript('game-mahjong'),loadFeatureScript('game-doudizhu')]);await loadFeatureScript('app-games')}else if(kind==='admin'){await loadFeatureScript('admin-economy');await loadFeatureScript('app-games')}}catch(e){toast(e.message||'功能模块加载失败');throw e}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c])}
function attr(s){return esc(s).replace(/`/g,'&#96;')}
function lastSeenText(ts){if(!ts)return'从未';const d=Math.max(0,Date.now()-ts);if(d<60000)return'刚刚';if(d<3600000)return`${Math.floor(d/60000)}分钟前`;if(d<86400000)return`${Math.floor(d/3600000)}小时前`;return new Date(ts).toLocaleDateString()}
async function localApi(path,obj=null){const opt=obj?{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(obj)}:{};const r=await fetch('/api/local-admin/'+path,opt),j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||`HTTP ${r.status}`);return j}

function slime(color='mint',cls='',userId=''){return `<span class="slime ${color} ${cls}"${userId?` data-user-id="${attr(userId)}" role="button" title="查看用户资料"`:''}></span>`}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),3200)}
function abortWithReason(ctrl,message='请求已取消',name='AbortError'){if(!ctrl||ctrl.signal?.aborted)return;let reason;try{reason=new DOMException(message,name)}catch{reason=Object.assign(new Error(message),{name})}try{ctrl.abort(reason)}catch{try{ctrl.abort(reason)}catch{}}}
