async function post(url,obj,{timeout=7000,retries=0}={}){let last;for(let attempt=0;attempt<=retries;attempt++){const ctrl=new AbortController(),timer=setTimeout(()=>abortWithReason(ctrl,'请求超时','TimeoutError'),timeout);try{const r=await fetch(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(obj),signal:ctrl.signal});let j;try{j=await r.json()}catch(parseErr){throw Error(r.ok?'响应不完整，请重试':`HTTP ${r.status}`)}if(!r.ok){const err=Error(j?.error||`HTTP ${r.status}`);err.status=r.status;err.payload=j;throw err}return j}catch(e){last=e;const timed=isAbortLike(e,ctrl.signal);if(!(timed&&attempt<retries))throw timed?Error('连接服务器超时，请检查网络后重试'):e;await new Promise(r=>setTimeout(r,500+attempt*350))}finally{clearTimeout(timer)}}throw last||Error('请求失败')}
function creds(extra={}){return {...state.identity,...extra}}
function browserName(){const ua=navigator.userAgent;return /Edg\//.test(ua)?'Edge':/OPR\//.test(ua)?'Opera':/Chrome\//.test(ua)?'Chrome':/Firefox\//.test(ua)?'Firefox':/Safari\//.test(ua)?'Safari':'浏览器'}
function deviceGuess(info=state.clientDeviceInfo){const p=info?.platform||(/Windows/i.test(navigator.userAgent)?'Windows':/Android/i.test(navigator.userAgent)?'Android':/iPhone|iPad/i.test(navigator.userAgent)?'iOS':'设备'),b=info?.browser||browserName(),a=info?.architecture?` · ${info.architecture}${info.bitness?` ${info.bitness}bit`:''}`:'';return `${p} · ${b}${a}`.slice(0,32)}
async function idbPut(k,v){try{const db=await openIdentityDb();await new Promise((resolve,reject)=>{const tx=db.transaction(identityDbStore,'readwrite');tx.objectStore(identityDbStore).put(v,k);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();return true}catch{return false}}
