async function loadOrCreateInstallId(preferred=''){let x=String(preferred||'');if(!x)try{x=String(localStorage.getItem('slimelounge.install.v1')||'')}catch{}if(!x)x=String(await idbGet('installId')||'');if(!x)x=makeTabId();try{localStorage.setItem('slimelounge.install.v1',x)}catch{}await idbPut('installId',x);return x}
async function collectDeviceInfo(){let high={};try{if(navigator.userAgentData?.getHighEntropyValues)high=await navigator.userAgentData.getHighEntropyValues(['platform','platformVersion','architecture','bitness','model'])}catch{}return {installId:state.clientInstallId,platform:high.platform||navigator.userAgentData?.platform||navigator.platform||'',platformVersion:high.platformVersion||'',architecture:high.architecture||'',bitness:high.bitness||'',model:high.model||'',browser:browserName(),language:navigator.language||'',timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone||'',screen:`${screen.width}x${screen.height}@${Number(devicePixelRatio||1).toFixed(2)}`,hardwareConcurrency:navigator.hardwareConcurrency||0,deviceMemory:navigator.deviceMemory||0,maxTouchPoints:navigator.maxTouchPoints||0}}
function clientDevicePayload(){return state.clientDeviceInfo||{installId:state.clientInstallId,browser:browserName()}}
const identityDbName='slimelounge-device-v1',identityDbStore='identity';
function validIdentity(x){return !!(x&&typeof x.userId==='string'&&typeof x.deviceId==='string'&&typeof x.deviceToken==='string'&&x.userId&&x.deviceId&&x.deviceToken)}
function openIdentityDb(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(Error('IndexedDB unavailable'));let done=false;const finish=(fn,v)=>{if(done)return;done=true;clearTimeout(timer);fn(v)},timer=setTimeout(()=>finish(reject,Error('IndexedDB open timeout')),1800),r=indexedDB.open(identityDbName,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(identityDbStore))r.result.createObjectStore(identityDbStore)};r.onsuccess=()=>finish(resolve,r.result);r.onerror=()=>finish(reject,r.error||Error('IndexedDB open failed'));r.onblocked=()=>finish(reject,Error('IndexedDB blocked'))})}
async function saveIdentityBackup(x){await idbPut('current',x);try{await navigator.storage?.persist?.()}catch{}}
async function loadIdentityBackup(){const x=await idbGet('current');return validIdentity(x)?x:null}
function saveIdentity(x){state.identity={userId:x.userId,deviceId:x.deviceId,deviceToken:x.deviceToken};try{localStorage.setItem(storeKey,JSON.stringify(state.identity))}catch{}void saveIdentityBackup(state.identity)}
function loadIdentity(){try{const x=JSON.parse(localStorage.getItem(storeKey)||'null');return validIdentity(x)?x:null}catch{return null}}
async function consumeOriginTransfer(){const u=new URL(location.href),t=u.searchParams.get('sl_transfer');if(!t)return null;u.searchParams.delete('sl_transfer');history.replaceState(null,'',u.pathname+(u.search||'')+u.hash);try{const r=await post('/api/origin-transfer/redeem',{transferToken:t},{timeout:6000});if(r.clientInstallId){state.clientInstallId=await loadOrCreateInstallId(r.clientInstallId);state.clientDeviceInfo={...(state.clientDeviceInfo||{}),installId:state.clientInstallId}}return r}catch(e){console.warn('origin identity transfer failed',e);return null}}
function isStaff(){return ['owner','admin'].includes(state.profile?.role)}
