function paintFriendUnread(unread={}){const total=Math.max(0,Number(unread.total??state.friendUnreadTotal)||0),byUser=unread.byUser||state.friendUnreadByUser||{};state.friendUnreadTotal=total;state.friendUnreadByUser=byUser;const b=$('#friendUnreadBadge');if(b){b.textContent=total>99?'99+':String(total);b.classList.toggle('hidden',!total)}}
async function pollFriendUnread(){if(!state.identity||document.hidden)return;try{const r=await post('/api/social/unread',creds({}),{timeout:3500});paintFriendUnread(r.unread||{})}catch{}}

function statusBadge(u){const s=u&&Object.prototype.hasOwnProperty.call(u,'online')&&u.online===false?'offline':(u?.presenceStatus||'online');return `<span class="status-badge status-${s}">${esc(STATUS_NAMES[s]||'在线')}</span>`}
function roleBadge(role){return role==='owner'?'<span class="role-badge owner">OWNER</span>':role==='admin'?'<span class="role-badge admin">ADMIN</span>':''}
function setConn(mode,text){const ok=mode==='online'||mode==='service';$('#connDot').style.color=ok?'#69e980':mode==='connecting'?'#f1ce68':'#d06072';$('#connText').textContent=text}
function paintSelf(){if(!state.profile)return;$('#selfName').textContent=`${state.profile.name} · ${statusLabel(state.profile)}`;const ss=$('#selfSlime');ss.className=`slime ${state.profile.slimeColor}`;ss.dataset.userId=state.profile.userId;$('#adminNav').classList.toggle('hidden',!isStaff());paintWalletWidgets()}
function walletEstimate(p=state.profile,now=Date.now()){if(!p)return 0;let v=Math.max(0,Number(p.chips)||0),floor=Number(p.chipFloor)||1000;if(v<floor){const elapsed=Math.max(0,now-(Number(p.chipsUpdatedAt)||now));v=Math.min(floor,v+floor*elapsed/(Number(p.chipRecoverMs)||3600000))}return Math.floor(v)}
function walletRecoveryText(p=state.profile,now=Date.now()){const v=walletEstimate(p,now),floor=Number(p?.chipFloor)||1000;if(v>=floor)return `余额 ≥ ${floor}，不自动回血`;const rate=floor/(Number(p?.chipRecoverMs)||3600000),left=Math.ceil((floor-v)/rate/1000),m=Math.floor(left/60),s=left%60;return `自动回血中 · ${m}:${String(s).padStart(2,'0')} 后恢复到 ${floor}`}
function paintWalletWidgets(){for(const e of $$('[data-wallet-chips]'))e.textContent=String(walletEstimate());for(const e of $$('[data-wallet-recovery]'))e.textContent=walletRecoveryText();for(const b of $$('[data-daily-checkin]')){b.disabled=!state.profile?.canChipCheckin;b.textContent=state.profile?.canChipCheckin?`每日签到 +${state.profile?.dailyChipReward||1000}`:'今日已签到'}}
async function dailyChipCheckin(){try{const r=await post('/api/wallet/checkin',creds({}),{timeout:5000});state.profile={...state.profile,...r.profile};paintSelf();toast(`签到成功 · +${r.reward||1000} 筹码`);if(state.section==='games'&&!state.roomTarget)renderRoomBrowser()}catch(e){toast(e.message)}}
async function loadDirectory(){if(!state.identity)return;try{const r=await post('/api/users/presence',creds({}),{timeout:4500});state.directoryUsers=r.users||[];renderDirectoryUsers()}catch{}}

function initColors(){const p=$('#colorPicker');p.innerHTML=COLORS.map(c=>`<button type="button" class="color-chip ${c===state.selectedColor?'selected':''}" data-color="${c}" title="${COLOR_NAMES[c]}">${slime(c)}</button>`).join('');p.onclick=e=>{const b=e.target.closest('button[data-color]');if(!b)return;state.selectedColor=b.dataset.color;$$('.color-chip').forEach(x=>x.classList.toggle('selected',x===b));$('#authSlime').className=`slime ${state.selectedColor} xl`;};}

function activeGameSession(){return state.gameSessionId?state.sessions[state.gameSessionId]:null}function activeMusicSession(){return state.musicSessionId?state.sessions[state.musicSessionId]:null}function sessionSeated(sess){const g=sess?.game;if(!g||!state.profile)return false;if(sess?.room?.single)return false;return ['gomoku','xiangqi','chess','go'].includes(g.kind)?(g.players||[]).includes(state.profile.userId):(g.seats||[]).some(x=>x?.userId===state.profile.userId)}function sessionGameActive(sess){const g=sess?.game;if(!g||sess?.room?.single)return false;if(['gomoku','xiangqi','chess','go'].includes(g.kind))return !!g.started&&!g.winner&&!g.result;if(g.kind==='dice')return g.phase==='playing';if(g.kind==='blackjack')return ['insurance','playing','dealer'].includes(g.phase);if(g.kind==='poker')return ['preflop','flop','turn','river','run_choice'].includes(g.phase);return ['uno','mahjong'].includes(g.kind)&&g.phase==='playing'}function effectivePresence(){const gs=activeGameSession(),ms=activeMusicSession();if(document.hidden)return {status:'away',label:'页面在后台',roomId:gs&&sessionSeated(gs)?gs.id:ms?ms.id:state.roomTarget||''};if(typeof leisureVisible!=='undefined'&&leisureVisible&&leisureKind==='market')return {status:'trading',label:'虚拟交易所',roomId:''};if(typeof leisureVisible!=='undefined'&&leisureVisible&&leisureKind==='fishing')return {status:'fishing',label:'史莱姆湖',roomId:''};if(gs&&sessionSeated(gs))return {status:'gaming',label:`${GAME_NAMES[gs.room?.game]||'游戏'} · ${gs.room?.name||''}`,roomId:gs.id};if(state.voiceRoomId){const vs=sessionFor(state.voiceRoomId);return {status:'voice',label:`语音中 · ${vs?.room?.name||'语音频道'}`,roomId:state.voiceRoomId}}if(ms)return {status:'listening',label:`听歌 · ${ms.room?.name||''}${ms.music?.title?` · ${ms.music.title}`:''}`,roomId:ms.id};if(Date.now()-state.lastInteractionAt>5*60*1000)return {status:'away',label:'长时间无操作',roomId:''};return {status:state.profile?.manualPresenceStatus||(['online','busy','away'].includes(state.profile?.presenceStatus)?state.profile.presenceStatus:'online'),label:'',roomId:state.roomTarget||''}}
function noteServiceOk(){state.serviceOnline=true;state.serviceFailCount=0;state.lastServiceOkAt=Date.now();if(!state.roomTarget)setConn('service','服务在线')}
function reportNetworkEvent(kind,detail='',sess=null,status=0,rttMs=0){if(!state.identity)return;const key=`${kind}|${sess?.id||''}|${String(detail).slice(0,80)}`,now=Date.now();if(now-(state.networkEventMarks[key]||0)<10000)return;state.networkEventMarks[key]=now;const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),2500);fetch('/api/client/network-event',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(creds({kind,detail:String(detail||'').slice(0,260),roomId:sess?.id||'',transport:sess?.transport||'',status,rttMs:Math.max(0,Math.round(Number(rttMs)||0))})),signal:ctrl.signal,keepalive:true}).catch(()=>{}).finally(()=>clearTimeout(timer))}
async function healthPing(){if(!state.identity)return;if(state.healthInFlight)return state.healthInFlight;state.healthInFlight=(async()=>{const ep=effectivePresence(),t0=performance.now();try{const r=await post('/api/sync/light',creds({section:state.section,roomId:ep.roomId,presenceStatus:ep.status,activityLabel:ep.label,tabId,tabState:document.hidden?'hidden':'visible',since:state.notifySince,includeUsers:state.section==='chat',includeSocial:state.section==='friends'}),{timeout:7000}),rtt=Math.max(0,Math.round(performance.now()-t0));state.lastHttpRttMs=rtt;if(Date.now()-(state.lastRttReportAt||0)>60000){state.lastRttReportAt=Date.now();reportNetworkEvent('rtt-sample',`大厅同步 RTT ${rtt}ms`,null,0,rtt)}noteServiceOk();if(r.profile){state.profile={...state.profile,...r.profile};paintSelf()}paintFriendUnread(r.unread||{});state.notifySince=r.now||Date.now();for(const x of r.notifications||[])showChannelNotify(x);if(Array.isArray(r.users)){state.directoryUsers=r.users;renderDirectoryUsers()}if(r.social)state.social=r.social}catch(e){if(e?.status===429){state.serviceOnline=true;state.serviceFailCount=0;if(!state.roomTarget)setConn('service','服务在线 · 后台同步稍后重试');reportNetworkEvent('light-sync-rate-limit',e.message,null,429);return}state.serviceFailCount=(state.serviceFailCount||0)+1;const recent=Date.now()-(state.lastServiceOkAt||0)<45000;if(!navigator.onLine){state.serviceOnline=false;if(!state.roomTarget)setConn('offline','网络离线')}else if(recent||state.serviceFailCount<3){if(!state.roomTarget)setConn('connecting','连接波动 · 自动恢复中')}else{state.serviceOnline=false;if(!state.roomTarget)setConn('offline','服务暂时不可达')}reportNetworkEvent('light-sync-error',e?.message||String(e),null,e?.status||0)}finally{state.healthInFlight=null}})();return state.healthInFlight}

async function boot(){
  setBootProgress(7,'正在初始化界面...');initColors();const fontTask=loadPixelFonts().catch(()=>false);
  setBootProgress(20,'正在准备设备身份...');state.clientInstallId=await loadOrCreateInstallId();
  setBootProgress(30,'正在识别当前设备...');state.clientDeviceInfo=await timed(collectDeviceInfo(),2200,'设备信息读取超时').catch(()=>({installId:state.clientInstallId,browser:browserName()}));
  const autoDeviceLabel=deviceGuess();$('#regDevice').value=autoDeviceLabel;if($('#deviceLinkDevice'))$('#deviceLinkDevice').value=autoDeviceLabel;if($('#ownerRecoverDevice'))$('#ownerRecoverDevice').value=autoDeviceLabel;
  if(isLocalServerHost()){$('#localIdentityBtn').classList.remove('hidden');$('#localIdentityBtn').onclick=()=>renderLocalIdentityManager(true)}
  setBootProgress(40,'正在检查账号迁移信息...');const transferred=await consumeOriginTransfer();if(transferred){saveIdentity(transferred);state.profile=transferred.profile;state.employeeMasked=transferred.employeeMasked;state.deviceLabel=transferred.deviceLabel;state.social=transferred.social||null;await fontTask;return enterApp()}
  setBootProgress(50,'正在读取本机登录信息...');state.identity=loadIdentity()||await loadIdentityBackup();
  if(state.identity){saveIdentity(state.identity);setBootProgress(60,'正在连接 SlimeLounge...');try{const a=await post('/api/auth',{...state.identity,tabId,deviceInfo:clientDevicePayload()},{timeout:4500});state.profile=a.profile;state.employeeMasked=a.employeeMasked;state.deviceLabel=a.deviceLabel;state.social=a.social;if(!isLocalServerHost()||state.profile.role==='owner'){await Promise.race([fontTask,sleep(700)]);return enterApp()}}catch(e){console.warn('saved identity auth failed',e)}}
  setBootProgress(70,'正在尝试恢复服务器会话...');try{const r=await timed(fetch('/api/session',{cache:'no-store'}),4500,'会话恢复超时');if(r.ok){const x=await r.json();saveIdentity(x);state.profile=x.profile;state.employeeMasked=x.employeeMasked;state.deviceLabel=x.deviceLabel;state.social=x.social||null;try{await post('/api/auth',{...state.identity,tabId,deviceInfo:clientDevicePayload()},{timeout:3000})}catch{}await Promise.race([fontTask,sleep(700)]);return enterApp()}}catch(e){console.info('device cookie recovery unavailable:',e.message)}
  if(isLocalServerHost()){setBootProgress(80,'正在检查本机 Owner 身份...');try{const x=await localApi('owner-session',{});saveIdentity(x);state.profile=x.profile;state.employeeMasked=x.employeeMasked;state.deviceLabel=x.deviceLabel;state.social=null;await Promise.race([fontTask,sleep(700)]);return enterApp()}catch(e){console.info('local owner auto recovery unavailable:',e.message)}}
  setBootProgress(95,'正在打开登录页面...');await Promise.race([fontTask,sleep(800)]);setBootProgress(100,'准备完成');$('#boot').classList.add('hidden');$('#authScreen').classList.remove('hidden')
}
