function startVoiceMeter(stream,sess){stopVoiceMeter(sess);const AC=globalThis.AudioContext||globalThis.webkitAudioContext;if(!AC)return;try{const ctx=new AC(),analyser=ctx.createAnalyser(),source=ctx.createMediaStreamSource(stream),buf=new Float32Array(512);analyser.fftSize=512;analyser.smoothingTimeConstant=.72;source.connect(analyser);let floor=.008;const timer=setInterval(()=>{if(!state.voiceEnabled||state.voiceRoomId!==sess?.id)return;analyser.getFloatTimeDomainData(buf);let sum=0;for(const v of buf)sum+=v*v;const rms=Math.sqrt(sum/buf.length),threshold=Math.max(.026,floor*2.7);if(rms<threshold*1.15)floor=Math.min(.04,floor*.96+rms*.04);if(rms>threshold)state.voiceLastLoudAt=Date.now()+380;const speaking=Date.now()<state.voiceLastLoudAt;if(speaking!==state.voiceSpeaking){state.voiceSpeaking=speaking;sendVoiceActivity(sess,speaking);updateVoiceButton()}},90);state.voiceMeter={ctx,analyser,source,timer}}catch(e){console.warn('[voice meter]',e)}}
