function voicePeer(sess,uid){let x=state.voicePeers.get(uid);if(x)return x;const pc=new RTCPeerConnection({iceServers:state.voiceIceServers||[{urls:['stun:stun.l.google.com:19302','stun:stun.cloudflare.com:3478']}]}),audio=document.createElement('audio');audio.autoplay=true;audio.playsInline=true;audio.className='voice-remote-audio';audio.dataset.voiceUser=uid;document.body.appendChild(audio);x={pc,audio,pendingCandidates:[]};state.voicePeers.set(uid,x);if(state.voiceStream){for(const t of state.voiceStream.getAudioTracks())pc.addTrack(t,state.voiceStream)}else try{pc.addTransceiver('audio',{direction:'recvonly'})}catch{}pc.ontrack=e=>{const stream=e.streams?.[0]||new MediaStream([e.track]);audio.srcObject=stream;audio.play().then(()=>{audio.dataset.blocked='' }).catch(()=>{audio.dataset.blocked='1';toast('语音已连接，但浏览器阻止了自动播放；请点击页面一次以允许听到对方声音')})};pc.onicecandidate=e=>{if(e.candidate)voiceSend(sess,uid,{kind:'candidate',candidate:e.candidate})};pc.onconnectionstatechange=()=>{if(['failed','closed'].includes(pc.connectionState))dropVoicePeer(uid)};return x}
async function makeVoiceOffer(sess,uid){if(state.voiceOfferBusy.has(uid)||uid===state.profile?.userId)return;state.voiceOfferBusy.add(uid);try{const x=voicePeer(sess,uid);const offer=await x.pc.createOffer();await x.pc.setLocalDescription(offer);voiceSend(sess,uid,{kind:'offer',sdp:x.pc.localDescription})}catch(e){console.warn('[voice offer]',e)}finally{state.voiceOfferBusy.delete(uid)}}
async function handleVoiceSignal(sess,m){if(!voiceCapable(sess)||state.roomTarget!==sess.id||!m.from||m.from===state.profile?.userId)return;try{const x=voicePeer(sess,m.from),sig=m.signal||{};if(sig.kind==='offer'&&sig.sdp){await x.pc.setRemoteDescription(sig.sdp);for(const c of x.pendingCandidates.splice(0))await x.pc.addIceCandidate(c).catch(()=>{});if(state.voiceStream){const hasTrack=x.pc.getSenders().some(z=>z.track?.kind==='audio');if(!hasTrack)for(const t of state.voiceStream.getAudioTracks())x.pc.addTrack(t,state.voiceStream)}const ans=await x.pc.createAnswer();await x.pc.setLocalDescription(ans);voiceSend(sess,m.from,{kind:'answer',sdp:x.pc.localDescription})}else if(sig.kind==='answer'&&sig.sdp){await x.pc.setRemoteDescription(sig.sdp);for(const c of x.pendingCandidates.splice(0))await x.pc.addIceCandidate(c).catch(()=>{})}else if(sig.kind==='candidate'&&sig.candidate){if(x.pc.remoteDescription)await x.pc.addIceCandidate(sig.candidate).catch(()=>{});else x.pendingCandidates.push(sig.candidate)}}catch(e){console.warn('[voice signal]',e)}}
function reconcileVoicePeers(sess){if(!voiceCapable(sess)||state.roomTarget!==sess.id)return;const remote=(sess.users||[]).filter(u=>u.userId!==state.profile?.userId),wanted=remote.filter(u=>state.voiceEnabled||u.voiceOn),ids=new Set(wanted.map(u=>u.userId));for(const uid of [...state.voicePeers.keys()])if(!ids.has(uid))dropVoicePeer(uid);for(const u of wanted){voicePeer(sess,u.userId);if(String(state.profile?.userId||'').localeCompare(String(u.userId))<0)void makeVoiceOffer(sess,u.userId)}}
async function ensureVoiceConfig(){if(state.voiceIceServers)return state.voiceIceServers;try{const r=await post('/api/voice/config',creds({}),{timeout:5000,retries:1});if(Array.isArray(r.iceServers)&&r.iceServers.length)state.voiceIceServers=r.iceServers}catch{}return state.voiceIceServers||(state.voiceIceServers=[{urls:['stun:stun.l.google.com:19302','stun:stun.cloudflare.com:3478']}])}
function unlockRemoteVoiceAudio(){for(const a of document.querySelectorAll('.voice-remote-audio'))if(a.srcObject&&a.paused)a.play().then(()=>{a.dataset.blocked=''}).catch(()=>{})}
document.addEventListener('pointerdown',unlockRemoteVoiceAudio,{passive:true});document.addEventListener('touchstart',unlockRemoteVoiceAudio,{passive:true});
async function toggleVoice(force=null){const sess=sessionFor(state.roomTarget);if(!voiceCapable(sess))return;if(sess.transport!=='websocket'||sess.ws?.readyState!==WebSocket.OPEN)return toast('语音需要 WebSocket 连接；HTTP 兼容连接暂不支持语音');const want=force==null?!state.voiceEnabled:!!force;if(!want)return stopVoice(true,sess);if(!navigator.mediaDevices?.getUserMedia)return toast('当前浏览器无法调用麦克风；手机/公网访问请使用 HTTPS/WSS 域名');if(!globalThis.isSecureContext&&!isLocalServerHost())return toast('移动端麦克风需要 HTTPS 安全页面；请用 HTTPS/WSS 域名访问');try{await ensureVoiceConfig();const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});if(state.voiceStream)for(const t of state.voiceStream.getTracks())t.stop();state.voiceStream=stream;state.voiceEnabled=true;state.voiceRoomId=sess.id;for(const [uid,x] of state.voicePeers){const existing=x.pc.getSenders().find(z=>z.track?.kind==='audio');const track=stream.getAudioTracks()[0];if(existing&&track)await existing.replaceTrack(track);else if(track)x.pc.addTrack(track,stream)}sess.ws.send(JSON.stringify({type:'voice_toggle',enabled:true}));startVoiceMeter(stream,sess);updateVoiceButton();reconcileVoicePeers(sess);for(const u of sess.users||[])if(u.userId!==state.profile?.userId)void makeVoiceOffer(sess,u.userId);toast('语音已开启 · 再按 V 或点击按钮关闭')}catch(e){toast(e?.name==='NotAllowedError'?'没有获得麦克风权限':'无法开启麦克风：'+(e.message||e))}}
$('#voiceToggle')?.addEventListener('click',()=>toggleVoice());
document.addEventListener('keydown',e=>{if(e.repeat||e.key.toLowerCase()!=='v')return;const t=e.target,typing=t?.matches?.('input,textarea,select,[contenteditable="true"]');if(typing||!voiceCapable())return;e.preventDefault();toggleVoice()});

function userName(id){if(String(id||'').startsWith('BOT:'))return '高级史莱姆 AI';return state.roomUsers.find(u=>u.userId===id)?.name||(id===state.profile?.userId?state.profile.name:'玩家')}
function renderMain(){const e=$('#roomMain');if(!e||!state.room)return;const y=e.scrollTop,x=e.scrollLeft,rid=state.roomTarget;if(state.room.category==='music')renderMusic(e);else if(state.room.category==='game')renderGame(e);requestAnimationFrame(()=>{if(state.roomTarget!==rid||!e.isConnected)return;e.scrollTop=Math.min(y,Math.max(0,e.scrollHeight-e.clientHeight));e.scrollLeft=Math.min(x,Math.max(0,e.scrollWidth-e.clientWidth))})}

function fmtMs(ms){ms=Math.max(0,Math.floor(ms||0));const s=Math.ceil(ms/1000),m=Math.floor(s/60);return `${m}:${String(s%60).padStart(2,'0')}`}
function serverNowFor(sess){return Date.now()-(sess?.serverOffset||0)}
function boardClockSnapshot(sess){const s=sess?.game;if(!s||!['gomoku','xiangqi','chess'].includes(s.kind))return null;const now=serverNowFor(sess),out=(s.timeBanks||[200000,200000]).slice();if(s.started&&s.turnStartedAt){const spent=Math.max(0,now-s.turnStartedAt-(s.turnFreeMs||10000));out[s.turn]=Math.max(0,out[s.turn]-spent)}return out}
function turnCountdown(sess){const s=sess?.game;if(!s||!s.turnStartedAt)return null;if(['go'].includes(s.kind)){if(!s.started)return null;return Math.max(0,(s.turnTimeoutMs||60000)-(serverNowFor(sess)-s.turnStartedAt))}if(s.turnSeat==null)return null;return Math.max(0,(s.turnTimeoutMs||30000)-(serverNowFor(sess)-s.turnStartedAt))}
function gameClockHtml(s){if(!s)return'';const sess=activeGameSession();if(['gomoku','xiangqi','chess'].includes(s.kind)){const t=boardClockSnapshot(sess)||s.timeBanks||[200000,200000];return `<div class="game-clockbar"><span class="clock-pill ${s.turn===0&&s.started?'turn':''}">玩家 1 固定时间 <b data-board-clock="0">${fmtMs(t[0])}</b></span><span class="clock-pill ${s.turn===1&&s.started?'turn':''}">玩家 2 固定时间 <b data-board-clock="1">${fmtMs(t[1])}</b></span></div><div class="auto-rule">每步前 ${Math.round((s.turnFreeMs||10000)/1000)} 秒为自由思考时间；之后消耗个人 ${Math.round((s.bankInitialMs||200000)/1000)} 秒固定时间。固定时间归零判负；切到后台不会触发判罚。</div>`}const tc=turnCountdown(sess);if(tc==null)return'';const rule=['go'].includes(s.kind)?'每回合 60 秒，超时判负；切到后台不影响对局。':s.kind==='mahjong'?'日麻出牌回合 30 秒，超时自动摸切/打出 AI 推荐牌；鸣牌响应另有倒计时。':s.kind==='uno'?'UNO 每回合 30 秒，超时自动摸牌并过牌。':'21点超时自动停牌；德州超时自动弃牌。切到后台不会触发任何游戏操作。';return `<div class="game-clockbar"><span class="clock-pill turn">当前操作剩余 <b data-card-clock>${fmtMs(tc)}</b></span></div><div class="auto-rule">${rule}</div>`}
function updateLiveTimers(){paintWalletWidgets();const sess=activeGameSession();if(sess?.game){const b=boardClockSnapshot(sess);if(b){$$('[data-board-clock]').forEach(e=>{const i=+e.dataset.boardClock;e.textContent=fmtMs(b[i]);e.parentElement?.classList.toggle('low',b[i]<30000)})}const c=turnCountdown(sess);if(c!=null){$$('[data-card-clock]').forEach(e=>{e.textContent=fmtMs(c);e.parentElement?.classList.toggle('low',c<10000)})}}const ge=$('#activityGameTimer');if(ge&&sess?.game){const b=boardClockSnapshot(sess);if(b)ge.textContent=`P1 ${fmtMs(b[0])} · P2 ${fmtMs(b[1])}`;else{const c=turnCountdown(sess);ge.textContent=c==null?'等待操作':`本轮 ${fmtMs(c)}`}}if(typeof updateMusicControlMirrors==='function')updateMusicControlMirrors()}
function activityGameText(sess){const s=sess?.game;if(!s)return'正在连接';if(['gomoku','xiangqi','chess'].includes(s.kind)){if(s.winner)return `${userNameInSession(sess,s.winner)} 获胜`;if(s.result==='stalemate')return'和棋';return s.started?`轮到 ${s.turn===0?'玩家 1':'玩家 2'}`:'等待准备'}return s.message||'游戏中'}
function userNameInSession(sess,id){if(String(id||'').startsWith('BOT:'))return'高级史莱姆 AI';return sess?.users?.find(u=>u.userId===id)?.name||(id===state.profile?.userId?state.profile.name:'玩家')}
